#!/usr/bin/env node
// Embeds the page and the rules into src/generated/assets.ts so the npm bundle and the single exe carry them
// without reading files next to the program. Run by npm run build, npm test, npm run typecheck.

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const page = readFileSync("src/ui/page.html", "utf8");
const rules = readFileSync("rules/rules.json", "utf8");
JSON.parse(rules);
const out =
  "// GENERATED by scripts/gen-assets.mjs from src/ui/page.html and rules/rules.json. Do not edit.\n" +
  `export const PAGE_HTML: string = ${JSON.stringify(page)};\n` +
  `export const RULES_TEXT: string = ${JSON.stringify(rules)};\n`;
mkdirSync("src/generated", { recursive: true });
writeFileSync("src/generated/assets.ts", out);
console.log(`gen-assets: page ${page.length} chars, rules ${rules.length} chars`);
